{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C39"],
      "claim": "Disopyramide, which shares the phenyl(2-pyridyl) central carbon and basic amine motif, had absolute oral bioavailability of 81.76 ± 17.90% in eight volunteers, directly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C49"],
      "claim": "Doxylamine, another phenyl(2-pyridyl) basic amine analogue, showed 50% oral bioavailability in normal subjects, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Fexofenadine, a piperidine tertiary-alcohol analogue, had absolute oral bioavailability of 41 ± 8.5% at a microdose and about 30% at therapeutic doses, still above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C48"],
      "claim": "Bepotastine, a piperidine pyridyl ether, showed >80% oral absorption/bioavailability in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Imidafenacin, a related phenyl-bearing basic drug, had absolute oral bioavailability of 57.8% in healthy subjects, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Loperamide is a low-bioavailability outlier (0.3%) driven by P-gp efflux and first-pass metabolism, but its very low transfer score and structural differences (amide, chlorophenyl, P-gp motif) make it a weak contradictory anchor.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted high (F ≥ 20%). The most transferable analogues—disopyramide, doxylamine, fexofenadine, bepotastine, and imidafenacin—all show human oral bioavailability of roughly 30–90%, despite basic amines and ionizable groups. The only low-F analogue, loperamide, has very low transferability and differs structurally. Physicochemical ionization is a concern but is not sufficient to overturn the consistent experimental evidence.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability data for the query molecule.",
    "No data on P-gp efflux or active transport for the query.",
    "First-pass metabolism and dose-dependent absorption are not directly assessed.",
    "The high basic pKa (10.35) and full ionization at pH 7.4 may affect permeability, but this is not experimentally quantified for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

